export class Periods {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly people = input.required<PersonWithClaims[]>();
  readonly periods = model<Period[]>([]);

  protected readonly dueTotals = computed(() => periodDueTotals(this.periods(), this.people()));
  protected readonly name = signal('');
  protected readonly from = signal('');
  protected readonly to = signal('');
  protected readonly error = signal('');
  /** The refusal of the last action on a period's row, shown on that row. */
  protected readonly rowError = signal<{ id: number; message: string } | null>(null);
  /** A submit still waiting for its answer: another press meanwhile is ignored. */
  private busy = false;

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.periods.set([]);
      this.name.set('');
      this.from.set('');
      this.to.set('');
      this.error.set('');
      this.rowError.set(null);
      if (sheet) void this.reload(sheet);
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async save(e: Event): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    this.error.set('');
    const sheet = this.session.sheet();
    if (!sheet) return;
    const name = this.name().trim();
    const from = this.from().trim() || (this.session.today() ?? '');
    const to = this.to().trim();
    if (!name) {
      this.error.set('Enter a name.');
      return;
    }
    if (!DATE.test(from) || !DATE.test(to)) {
      this.error.set('Enter a from-date and a to-date.');
      return;
    }
    if (to < from) {
      this.error.set('The to-date is before the from-date.');
      return;
    }
    const headers = { 'X-User': this.session.user() ?? '' };
    this.busy = true;
    try {
      const saved = await firstValueFrom(
        this.http.post<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { name, from, to }, { headers }),
      );
      if (this.session.sheet() !== sheet) return;
      this.periods.update((ps) => [...ps.filter((p) => p.id !== saved.id), saved].sort((a, b) => a.from.localeCompare(b.from)));
      this.name.set('');
      this.from.set('');
      this.to.set('');
    } catch (err) {
      if (this.session.sheet() !== sheet) return;
      const message = err instanceof HttpErrorResponse && err.status === 409
        ? (err.error?.message ?? 'That period name is already in use on this sheet.')
        : 'Could not add the period.';
      this.error.set(message);
    } finally {
      this.busy = false;
    }
  }

  /**
   * Close a period, fixing its due-total, or reopen a closed one (a steward only), making it live again;
   * a refusal is shown on its row.
   */
  protected async act(p: Period, action: 'close' | 'reopen'): Promise<void> {
    if (this.busy) return;
    this.rowError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const headers = { 'X-User': this.session.user() ?? '' };
    this.busy = true;
    try {
      const saved = await firstValueFrom(
        this.http.post<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${p.id}/${action}`, null, { headers }),
      );
      if (this.session.sheet() !== sheet) return;
      this.periods.update((ps) => ps.map((q) => (q.id === saved.id ? saved : q)));
    } catch (err) {
      if (this.session.sheet() !== sheet) return;
      const message = err instanceof HttpErrorResponse && err.status === 409
        ? (err.error?.message ?? (action === 'close' ? 'The period is already closed.' : 'The period cannot be reopened.'))
        : `Could not ${action} the period.`;
      this.rowError.set({ id: p.id, message });
    } finally {
      this.busy = false;
    }
  }

  private async reload(sheet: string): Promise<void> {
    const loads = this.session.loads();
    const periods = await firstValueFrom(this.http.get<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`));
    if (this.session.sheet() === sheet && this.session.loads() === loads) this.periods.set(periods);
  }
}
-- A sheet's periods: a name, unique on the sheet without regard to case, and a from and to date,
-- both inclusive. No two periods on a sheet overlap (checked when one is added).
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    name_key  VARCHAR(100) GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CONSTRAINT period_dates CHECK (from_date <= to_date),
    CONSTRAINT period_name_unique UNIQUE (sheet_id, name_key)
);
CREATE INDEX period_sheet ON period (sheet_id, from_date);
-- Whether a period is closed, and its due-total fixed when it was closed: later rate changes do not
-- alter it. Null while the period is open.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
-- The sheet's period numbering from: while set and the sheet's today is on or after it, a claim opened
-- is numbered within the period its date falls in (<period name>-<n>), or X-<n> when in no period;
-- null (blank) means off, and claims take the sheet-wide number.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim numbered within a period: the sequence it counts in ('P<period id>', or 'X' for no period),
-- its place in that sequence (1, 2, ...) and the number as shown; all null for a sheet-wide number.
ALTER TABLE claim ADD COLUMN period_sequence VARCHAR(30);
ALTER TABLE claim ADD COLUMN period_seq_number INT;
ALTER TABLE claim ADD COLUMN period_number VARCHAR(120);
ALTER TABLE claim ADD CONSTRAINT claim_period_number_unique UNIQUE (sheet_id, period_sequence, period_seq_number);
-- A correction names the number of the claim it corrects as shown, a sheet-wide or a period number.
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);

